import{_ as a,o as e,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"尾声：给妈妈的信","description":"","frontmatter":{},"headers":[],"relativePath":"books/jingying-weilai/13-尾声：给妈妈的信.md","filePath":"books/jingying-weilai/13-尾声：给妈妈的信.md","lastUpdated":1795076791000}'),o={name:"books/jingying-weilai/13-尾声：给妈妈的信.md"};function i(n,p,r,s,l,d){return e(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="尾声-给妈妈的信" tabindex="-1">尾声：给妈妈的信 <a class="header-anchor" href="#尾声-给妈妈的信" aria-label="Permalink to &quot;尾声：给妈妈的信&quot;">​</a></h1><p>妈妈：</p><p>2007年12月20日凌晨的这个时间，我呼唤您。</p><p>妈妈，我的妈妈。</p><p>您的儿子成了这个国家的总统。就像我小时候您经常教导我的那样，现在我成了一个真正能帮助邻居、老人、弱者、需要工作的年轻人、皱纹日益增多的家长、白天工作晚上学习的产业主力军以及这个国家所有国民的人。</p><p>昨天晚上确定当选的10点左右，我在汝矣岛大国家党竞选总部发表了胜选致辞，回到家时已经12点多了。其间见了很多人，他们一致为我的当选而高兴，而我却深深感悟到给予我的历史使命将是更大更重的。</p><p>妈妈，刚才在回家的路上，我突然想起小时候，您微笑着给我盛了满满一碗米饭，当时虽然您是微笑着，但眼睛里却含着泪水……</p><p>那天就是我的生日，是妈妈您给予我生命的日子，12月19日。应该是我在浦项上小学二三年级的时候吧。</p><p>妈妈您经常对我说：</p><p>“明博啊，你已经长这么大了，该懂得为别人做事了。”</p><p>哪家邻居有红白喜事之类的，您总是让我过去帮忙，还叮嘱我说：</p><p>“干活卖力点，但绝对不能吃人家的东西，一口水也不能喝。”</p><p>那时候我虽然不明白妈妈的意思，但我还是按您的话去做了。其实，在别人家碰钉子的次数也不少，但我怕妈妈您难过，没告诉您。有的人家以为我不是去帮忙，而是去混饭吃的，所以看我的目光都是冷冰冰的。我觉得委屈，心里也抱怨过；但是后来，我懂得了妈妈的心意。虽然我们很穷，但我们还是可以堂堂正正地去帮助别人，甚至帮助富人。在时时刻刻担心温饱的处境中，妈妈把我培养成了一个心灵富足的人。所以后来在社会上，无论遇到多么位高权重的人，我都可以毫不畏缩、堂堂正正地说出自己的信念。</p><p>在小时候那么贫穷的状况下还能对邻居有所帮助，这一点让我养成了很好的习惯，即不是从他人那儿得到些什么，而是相反的给予别人的习惯。把别人的困难当成自己的那种助人为乐的态度也是因为有了当时的体验。正是从那时候起，我养成了设身处地为他人着想的习惯。 妈妈，如果不是您的教导，我怎么能在一生中遇到那么多帮助我的人呢？您的那句“和从别人那儿得到相比，给予别人才是更幸福、更有价值的”的话，比起这世界上任何学校的教育更有价值。</p><p>妈妈，您还记得那一年，我因为“6·3”示威活动被关进西大门监狱，您来探视我的情景吗？</p><p>见面后您就问我：“你学习吗？祷告吗？读《圣经》吗？”</p><p>妈妈，我永远记得您当时含着眼泪的样子，我知道这三个问题是您内心最深处对我的牵挂，是我平生难以忘记的冲击性话语。</p><p>然后，您只对我说：“我相信你。按照自己的信念去做吧，我会为你祈祷的。”没有问一句我的身体、我在狱中的情况，您就转身走了。</p><p>妈妈，我永不能忘记您的祈祷：</p><p>“我们的博，希望他健康成长。”</p><p>从我出世，到您离世，二十多年如一日，每天凌晨为我祈祷。正是这祈祷，成就了今天的我。到现在，您的那些祷告还在我的耳边萦绕着。每当想起妈妈的那祷告，我就精力充沛。</p><p>您对我的教导几十年来一直鞭策着我。我在12月7日发表了捐出全部财产回报社会的声明，也是因为有您的教导。有人嘲笑说这是为总统选举拉票而玩弄的权术，但您知道我不是这这种人。我会遵守这个约定的，因为这也是跟您的约定啊。</p><p>请妈妈监督我。</p><p>我要遵照您的话，做一个为国家献身、没有任何私心的总统。</p><p>我将要做的事情很多：</p><p>我要用战胜不堪回首的贫穷的经验，建设一个让那些努力工作的人能成功的国家；</p><p>要在这个国家消除贫穷，让所有人都过上幸福的生活；</p><p>要把国民放在首位服务于他们，让我们的国家充满生机；</p><p>要使我们国民朝着再次繁荣的目标奋勇前进。</p><p>妈妈，我会一直在前面，竭尽全力飞奔的。</p><p>只要我还有些力气，我会不停息地奔跑的。</p><p>妈妈，我爱你！</p><p>2007年12月20日凌晨</p><p>明博　敬上</p>',34)])])}const f=a(o,[["render",i]]);export{m as __pageData,f as default};
